<section class="page-hero page-hero-compact"><div class="container"><span class="eyebrow">OPPORTUNITY EDITOR</span><h1><?= $editing ? 'Edit opportunity' : 'Create an opportunity' ?></h1><p>Complete the details candidates need to make an informed application.</p></div></section>
<section class="section"><div class="container form-layout">
    <form class="panel form-stack" method="post" action="<?= e(pageUrl('opportunity-form', $editing ? ['id' => (int) $item['id']] : [])) ?>">
        <?= formToken() ?><input type="hidden" name="action" value="<?= $editing ? 'update_opportunity' : 'create_opportunity' ?>"><?php if ($editing): ?><input type="hidden" name="opportunity_id" value="<?= e($item['id']) ?>"><?php endif; ?>
        <div class="form-section-heading"><h2>Opportunity information</h2><p>New and updated listings are saved as drafts and require review before publication.</p></div>
        <label class="field"><span>Opportunity title</span><input name="title" required maxlength="180" value="<?= e($item['title'] ?? '') ?>"></label>
        <label class="field"><span>Category</span><select name="category_id" required><option value="">Select a category</option><?php foreach ($categories as $category): ?><option value="<?= e($category['id']) ?>" <?= (int) ($item['category_id'] ?? 0) === (int) $category['id'] ? 'selected' : '' ?>><?= e($category['name']) ?></option><?php endforeach; ?></select></label>
        <label class="field"><span>Description</span><textarea name="description" rows="7" required maxlength="20000"><?= e($item['description'] ?? '') ?></textarea></label>
        <label class="field"><span>Responsibilities</span><textarea name="responsibilities" rows="4" maxlength="10000"><?= e($item['responsibilities'] ?? '') ?></textarea></label>
        <label class="field"><span>Requirements</span><textarea name="requirements" rows="4" maxlength="10000"><?= e($item['requirements'] ?? '') ?></textarea></label>
        <label class="field"><span>Qualifications</span><textarea name="qualifications" rows="4" maxlength="10000"><?= e($item['qualifications'] ?? '') ?></textarea></label>
        <label class="field"><span>Required skills (comma separated)</span><input name="required_skills" maxlength="1000" value="<?= e($item['required_skills'] ?? '') ?>"></label>
        <div class="field-row"><label class="field"><span>Location</span><input name="location" maxlength="180" value="<?= e($item['location'] ?? '') ?>"></label><label class="field"><span>Work arrangement</span><select name="work_arrangement"><?php foreach (['not_specified'=>'Not specified','on_site'=>'On-site','hybrid'=>'Hybrid','remote'=>'Remote'] as $value => $label): ?><option value="<?= e($value) ?>" <?= ($item['work_arrangement'] ?? 'not_specified') === $value ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select></label></div>
        <div class="field-row"><label class="field"><span>Compensation</span><input name="compensation" maxlength="180" value="<?= e($item['compensation'] ?? '') ?>" placeholder="e.g. GHS 2,000 monthly or unpaid"></label><label class="field"><span>Duration</span><input name="duration" maxlength="100" value="<?= e($item['duration'] ?? '') ?>" placeholder="e.g. 6 months"></label></div>
        <div class="field-row"><label class="field"><span>Application deadline</span><input type="date" name="application_deadline" value="<?= e($item['application_deadline'] ?? '') ?>"></label><label class="field"><span>Start date</span><input type="date" name="start_date" value="<?= e($item['start_date'] ?? '') ?>"></label></div>
        <label class="field"><span>Application method</span><select name="application_method"><option value="platform" <?= ($item['application_method'] ?? 'platform') === 'platform' ? 'selected' : '' ?>>Apply through Campus2Career</option><option value="external" <?= ($item['application_method'] ?? '') === 'external' ? 'selected' : '' ?>>External application link</option></select></label>
        <label class="field"><span>External application URL (required for external applications)</span><input type="url" name="application_url" maxlength="1000" value="<?= e($item['application_url'] ?? '') ?>" placeholder="https://"></label>
        <label class="field"><span>Contact email</span><input type="email" name="contact_email" maxlength="190" value="<?= e($item['contact_email'] ?? '') ?>"></label>
        <div class="form-actions"><button class="button button-primary" type="submit">Save draft</button><a class="button button-outline" href="<?= e(pageUrl('employer')) ?>">Cancel</a></div>
    </form>
    <aside class="panel"><span class="eyebrow">LISTING CHECKLIST</span><h2>Help candidates decide.</h2><ul class="check-list"><li>Use a clear, specific title.</li><li>Include responsibilities and eligibility requirements.</li><li>Be transparent about compensation and location.</li><li>Set a realistic application deadline.</li><li>Only publish accurate, current information.</li></ul></aside>
</div></section>
